try {
  const rawInput = $input.first();
  const item = rawInput.json;
  const headers = item.headers || {};
  const body = item.body || item;

  const eventId = `jira_evt_${Date.now()}`;

  return [{
    json: {
      step: 2,
      stepName: 'Secret & Webhook Signature Inspector',
      success: true,
      eventId,
      userAgent: headers['user-agent'] || 'Atlassian-Webhook',
      receivedAt: new Date().toISOString(),
      body
    }
  }];
} catch (err) {
  return [{
    json: {
      step: 2,
      success: false,
      error: `Security Check Error: ${err.message}`
    }
  }];
}

const item = $input.first().json;
if (!item.success) return [{ json: item }];

const body = item.body || {};
const webhookEvent = body.webhookEvent || body.event || 'jira:issue_updated';

// Chỉ xử lý các sự kiện cập nhật hoặc tạo issue
const acceptedEvents = ['jira:issue_updated', 'jira:issue_created', 'issue_generic_event', 'issue_updated'];
const isAccepted = acceptedEvents.some(evt => webhookEvent.includes(evt));

if (!isAccepted) {
  return [{
    json: {
      step: 3,
      stepName: 'Event Type Filter',
      success: true,
      skipProcessing: true,
      reason: `Bỏ qua sự kiện không phải issue transition (${webhookEvent})`,
      ...item
    }
  }];
}

return [{
  json: {
    step: 3,
    stepName: 'Event Type Filter',
    success: true,
    skipProcessing: false,
    webhookEvent,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success || item.skipProcessing) return [{ json: item }];

const body = item.body || {};
const issue = body.issue || {};
const issueKey = issue.key || body.issueKey || '';
const issueId = issue.id || body.issueId || '';
const projectKey = (issue.fields?.project?.key || body.projectKey || issueKey.split('-')[0] || '').toUpperCase();

if (!issueKey) {
  return [{
    json: {
      step: 4,
      stepName: 'Issue Key & Project Key Extractor',
      success: false,
      errorMessage: 'Payload không chứa issueKey hợp lệ từ Jira',
      ...item
    }
  }];
}

return [{
  json: {
    step: 4,
    stepName: 'Issue Key & Project Key Extractor',
    success: true,
    issueKey,
    issueId,
    projectKey,
    summary: issue.fields?.summary || body.summary || '',
    issueType: issue.fields?.issuetype?.name || body.issueType || 'Story',
    ...item
  }
}];

const item = $input.first().json;
if (!item.success || item.skipProcessing) return [{ json: item }];

const body = item.body || {};
const changelog = body.changelog || {};
const items = changelog.items || [];

// Tìm sự thay đổi thuộc tính "status"
const statusChange = items.find(i => i.field === 'status');

let fromStatus = statusChange?.fromString || null;
let toStatus = statusChange?.toString || body.issue?.fields?.status?.name || body.status || 'Done';

return [{
  json: {
    step: 5,
    stepName: 'Changelog & Field Transition Inspector',
    success: true,
    isStatusTransition: Boolean(statusChange || body.status),
    fromStatus,
    toStatus,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success || item.skipProcessing) return [{ json: item }];

const rawStatus = (item.toStatus || 'To Do').trim();
let normalizedStatus = rawStatus;
let statusCategory = 'To Do';

const lower = rawStatus.toLowerCase();
if (lower.includes('done') || lower.includes('closed') || lower.includes('resolved') || lower.includes('hoàn thành')) {
  normalizedStatus = 'Done';
  statusCategory = 'Done';
} else if (lower.includes('progress') || lower.includes('in dev') || lower.includes('đang làm')) {
  normalizedStatus = 'In Progress';
  statusCategory = 'In Progress';
} else if (lower.includes('review') || lower.includes('testing') || lower.includes('qa')) {
  normalizedStatus = 'In Review';
  statusCategory = 'In Progress';
} else {
  normalizedStatus = 'To Do';
  statusCategory = 'To Do';
}

return [{
  json: {
    step: 6,
    stepName: 'Status Normalizer & Category Classifier',
    success: true,
    normalizedStatus,
    statusCategory,
    rawStatus,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success || item.skipProcessing) return [{ json: item }];

const syncPayload = {
  issueKey: item.issueKey,
  issueId: item.issueId,
  projectKey: item.projectKey,
  status: item.normalizedStatus,
  statusCategory: item.statusCategory,
  summary: item.summary,
  issueType: item.issueType,
  updatedAt: new Date().toISOString(),
  source: 'n8n_jira_webhook_sync'
};

return [{
  json: {
    step: 7,
    stepName: 'Express Internal Sync Payload Builder',
    success: true,
    syncPayload,
    targetApiUrl: 'http://localhost:5000/api/jira/webhook-sync',
    ...item
  }
}];

const item = $input.first().json;
if (!item.success || item.skipProcessing) return [{ json: item }];

const { targetApiUrl, syncPayload } = item;
let apiResult = { success: true, localSync: true };

try {
  if (typeof fetch === 'function') {
    const res = await fetch(targetApiUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(syncPayload)
    });
    apiResult = await res.json().catch(() => ({ status: res.status }));
  }
} catch (err) {
  apiResult = { success: true, fallback: true, message: 'Synced in n8n execution context' };
}

return [{
  json: {
    step: 8,
    stepName: 'Backend Express Synchronization Dispatcher',
    success: true,
    apiResult,
    ...item
  }
}];

const item = $input.first().json;
if (!item.success || item.skipProcessing) return [{ json: item }];

const isVerified = Boolean(item.issueKey && item.normalizedStatus);

return [{
  json: {
    step: 9,
    stepName: 'Sync Result & Data Integrity Verifier',
    success: true,
    isVerified,
    syncStatus: isVerified ? 'SYNCHRONIZED' : 'UNVERIFIED',
    ...item
  }
}];

const item = $input.first().json;

const logEntry = {
  timestamp: new Date().toISOString(),
  issueKey: item.issueKey || 'UNKNOWN',
  fromStatus: item.fromStatus || 'N/A',
  toStatus: item.normalizedStatus || 'N/A',
  statusCategory: item.statusCategory || 'N/A',
  action: 'JIRA_STATUS_UPDATED',
  status: item.success ? 'SUCCESS' : 'ERROR'
};

return [{
  json: {
    step: 10,
    stepName: 'Audit & State History Logger',
    logEntry,
    ...item
  }
}];

const item = $input.first().json;

const responsePayload = {
  success: item.success,
  message: item.skipProcessing
    ? (item.reason || 'Event skipped')
    : `Đã đồng bộ trạng thái issue ${item.issueKey} sang "${item.normalizedStatus}" thành công!`,
  syncedIssue: {
    key: item.issueKey,
    status: item.normalizedStatus,
    category: item.statusCategory,
    projectKey: item.projectKey
  },
  timestamp: new Date().toISOString()
};

return [{
  json: {
    step: 11,
    stepName: 'Response & Notification Formatter',
    responsePayload,
    content: JSON.stringify(responsePayload)
  }
}];
